B.Qz=new A.bd("escuela_ruben_dario","Escuela Rub\xe9n Dar\xedo",B.aI,"El edificio escolar se inaugur\xf3 en 1952.","El edificio escolar se inaugur\xf3 en 1952 con el nombre de Escuela Rub\xe9n Dar\xedo. Sigue en la V\xeda 103, la ruta nacional 103, como escuela del Ministerio de Educaci\xf3n P\xfablica. Esa ruta y la ruta nacional 5 son las dos que cruzan el distrito.",1952,null,9.974945,-84.096325,B.Q,B.M2)
B.Qi=new A.bd("plaza_de_futbol","Plaza de F\xfatbol",B.aI,"Se inaugur\xf3 el 10 de marzo de 1968.","Se inaugur\xf3 el 10 de marzo de 1968. Antes, la primera cancha del pueblo y los festejos estaban en la plazoleta.",1968,null,9.973544,-84.095866,B.Q,B.ah)
B.QI=new A.bd("cen_cinai","CEN-CINAI",B.aI,"El Centro de Nutrici\xf3n se inaugur\xf3 en 1973.","El Centro de Nutrici\xf3n se inaugur\xf3 en 1973. El CEN-CINAI de Santa Rosa sigue en el registro nacional, c\xf3digo 4030601, diagonal a Perimercados, tel\xe9fono 2244-5844.",1973,null,9.973488,-84.098191,B.Q,B.ah)
